import org.jsoup.Connection.KeyVal;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.URL;

import static org.junit.Assert.assertEquals;

public class UrlBuilderTest {

    // Tests for the build() method
    @Test
    public void build_ValidUrl() throws Exception {
        URL inputUrl = new URL("https://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL actualUrl = urlBuilder.build();
        assertEquals("https://www.example.com", actualUrl.toString());
    }

    @Test(expected = MalformedURLException.class)
    public void build_InvalidUrl() throws Exception {
        URL inputUrl = new URL("invalid url");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.build(); // throws MalformedURLException
    }

    // Tests for the appendKeyVal() method
    @Test
    public void appendKeyVal_ValidKeyVal() throws UnsupportedEncodingException {
        URL inputUrl = new URL("https://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        KeyVal keyVal = new KeyVal("key", "value", false);
        urlBuilder.appendKeyVal(keyVal);
        assertEquals("https://www.example.com?key=value", urlBuilder.build().toString());
    }

}
```

This test class generates unit tests for the `build()` and `appendKeyVal()` methods of the `UrlBuilder` class. The tests use JUnit 4 to verify the correctness of the methods' behavior. The `build_ValidUrl` test checks if the `build()` method correctly converts a valid URL to a `URL` object, while the `build_InvalidUrl` test verifies that an invalid URL throws a `MalformedURLException`. The `appendKeyVal_ValidKeyVal` test checks if the `appendKeyVal()` method correctly appends a valid key-value pair to the URL.
